const fs = require('fs');
const a = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const total = a.reduce((sum, x) => sum + x, 0);
let possible = false;

if (total % 3 === 0) {
  const target = total / 3;

  for (let i = 0; i < 6; i++) {
    if (a[i] !== target) continue;

    for (let j = 0; j < 6; j++) {
      if (j === i) continue;

      for (let k = j + 1; k < 6; k++) {
        if (k !== i && a[j] + a[k] === target) {
          possible = true;
        }
      }
    }
  }
}

console.log(possible ? 'S' : 'N');
